pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut arrival_times = input.as_array().unwrap();
    let mut total_wait = 0i64;
    let mut current_time = 0i64;

    for item in arrival_times {
        let arr = item.as_array().unwrap();
        let arrival = arr[0].as_i64().unwrap();
        let duration = arr[1].as_i64().unwrap();

        // The job arrives at `arrival`, and service starts at `max(arrival, current_time)`
        let start_time = current_time.max(arrival);
        let wait_time = start_time - arrival;
        total_wait += wait_time;

        // Update current time to when service finishes
        current_time = start_time + duration;
    }

    serde_json::json!(total_wait)
}
